// Block (composition) — an email invitation form with a responsive role row.
// Form fields and actions own their look/behavior; Stack owns responsive arrangement.
import type { FormEvent, Ref } from "react";
import { Alert } from "../components/Alert";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Select, SelectItem } from "../components/Select";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./InviteForm.css";

export interface InviteFormProps {
  heading?: string;
  roles: { id: string; label: string }[];
  onSubmit?: (data: { email: string; role: string }) => void;
  isPending?: boolean;
  errorMessage?: string;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function InviteForm({
  heading,
  roles,
  onSubmit,
  isPending,
  errorMessage,
  className,
  ref,
}: InviteFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      email: String(data.get("email") ?? ""),
      role: String(data.get("role") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-inviteform ${className}` : "sd-inviteform"}
    >
      {/* `large`: this holds a fields GROUP and a submit, which is the shape the other nine
          full forms take. `small` is for a Stack holding field(s) DIRECTLY beside their button. */}
      <Stack gap="large" className="sd-inviteform__content">
        {heading && (
          <>
            <h2 className="sd-inviteform__heading sd-type-title-medium">{heading}</h2>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack direction={{ small: "column", medium: "row" }} gap="medium" className="sd-inviteform__fields">
          <TextField
            label="Email"
            name="email"
            type="email"
            autoComplete="email"
            isRequired
            className="sd-inviteform__email"
          />
          <Select
            label="Role"
            name="role"
            isRequired
            defaultSelectedKey={roles[0]?.id}
            className="sd-inviteform__role"
          >
            {roles.map((role) => (
              <SelectItem key={role.id} id={role.id}>
                {role.label}
              </SelectItem>
            ))}
          </Select>
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Send invite
        </Button>
      </Stack>
    </Form>
  );
}

/* InviteForm.css — .sd-inviteform (Block)
   Arrangement only: caps the form and lets both responsive fields share the row. */
.sd-inviteform {
  width: 100%;
}

.sd-inviteform__heading {
  margin: 0;
}

.sd-inviteform__email,
.sd-inviteform__role {
  flex: 1;
  min-width: 0;
}
